mapper.select:
SELECT id, document_id, version_no, source_checksum, parser_version, schema_version,
       artifact_key, artifact_checksum, status, created_at, updated_at
FROM knowledge_parse_artifact
WHERE document_id = #{documentId}
  AND version_no = #{versionNo}
  AND source_checksum = #{sourceChecksum}
  AND parser_version = #{parserVersion}
  AND schema_version = #{schemaVersion}
